import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long input = scanner.nextLong();

        long[] powerArr = new long[19];
        powerArr[0] = 1;
        for (int i = 1; i <= 18; ++i) {
            powerArr[i] = powerArr[i - 1] * 10;
        }

        long[] sumArr = new long[19];
        sumArr[0] = 0;
        for (int i = 1; i <= 18; ++i) {
            sumArr[i] = sumArr[i - 1] + powerArr[i];
        }

        int maxLevel = 1;
        while (maxLevel <= 18 && sumArr[maxLevel] <= input) {
            ++maxLevel;
        }
        --maxLevel;

        int[] minCost = {Integer.MAX_VALUE};

        explore(maxLevel, input, 0, powerArr, minCost);

        System.out.println(minCost[0]);
        scanner.close();
    }

    private static void explore(int level, long val, int cost, long[] powerArr, int[] minCost) {
        if (val == 0) {
            if (cost < minCost[0]) {
                minCost[0] = cost;
            }
            return;
        }
        if (level == 0) return;

        long base = powerArr[level];
        int i;
        for (i = -10; i * base <= val; ++i);
        // Explore with i-1
        explore(level - 1, val - (i - 1) * base, cost + Math.abs(i - 1) * (level + 1), powerArr, minCost);
        // Explore with i
        explore(level - 1, val - i * base, cost + Math.abs(i) * (level + 1), powerArr, minCost);
    }
}
